using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.HalfFock;

internal sealed class NormFourLowestGradesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual norm-four twisted zero mode on the ground and complete first half-oscillator grade.",
        H("Norm-Four Twisted Lowest Grades"),
        Blocks(
            Paragraph(Text("Let D be finite-rank lattice data with an integral symmetric Gram matrix and even diagonal, and assume its determinant is a unit to obtain the chosen actual twisted ground. Write B for its bilinear form and U for the actual ground action of a charge a with B(a,a)=4. The ordinary lattice state is vector=(1/16)quadraticState+(s/4)chargedState. Its corrected twisted field is used throughout.")),
            Paragraph(Text("The half-mode normal-pair contraction has only the surviving indices -1 and 0 on a first oscillator, and vanishes on the ground. The finite quadratic correction contributes G(i,j)/8. For the charged coefficient, the translated first oscillator has support contained in {0,1}; its creation coefficients are 1 and 2P. These contractions give both action formulas.")),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-zeromode"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.zeroMode"), H("The actual corrected zero mode"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For arbitrary even integral symmetric lattice data D, a unit Gram determinant hu, a charge a and a complex scalar s, L is correctedField(D,hu,vector(D,a,s)).coeff(-4). The exponent is the native doubled exponent of the physical weight-two zero mode."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-zeromode-ground"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.zeroMode_ground"), H("Action on the actual twisted ground"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every charge a of squared norm four, every complex s and every u in the chosen actual ground, L(1 tensor u)=(1/32)(1 tensor u)+(s/32)(1 tensor Uu), where U is groundAction(D,hu,a). No condition on s squared is needed for this formula."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-zeromode-x"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.zeroMode_X"), H("Action on each first half oscillator"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every charge a of squared norm four, every complex s, every coordinate i and every actual ground vector u, put b_i=B(a,unitCharge(i)) and P=sum_j a_j X(j,0). Then L(X(i,0) tensor u)=((1/32)X(i,0)+(b_i/16)P) tensor u+(s/32)((X(i,0)-2b_i P) tensor Uu)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-actualgrade-one-eq-span"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.actualGrade_one_eq_span"), H("The complete first half-oscillator grade"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every D and hu, actualGrade(D,hu,1) equals the complex span of all X(i,0) tensor u, with i ranging over every coordinate and u over the entire chosen ground. This is the full eigenspace of the original actualTensorL0 with eigenvalue rank(D)/16+1/2. Every odd-weight-one monomial is a single variable at mode zero; the ambient tensor basis proves exhaustion."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-actualgradeonezeromode"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.actualGradeOneZeroMode"), H("Restriction to the complete actual grade"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every norm-four a and every complex s, the computed action preserves the complete grade actualGrade(D,hu,1). Its restriction defines the endomorphism actualGradeOneZeroMode on that grade."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("normfourlowestgrades-actualgradeonezeromode-polynomial"), DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/NormFourLowestGrades.actualGradeOneZeroMode_polynomial"), H("Cubic of the actual restricted zero mode"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every D, hu, norm-four a and complex s satisfying s squared equal to one, the actual restricted endomorphism satisfies L(L-(1/16)I)(L-(1/2)I)=0. Repeated application to X(i,0) tensor u uses U squared equal to the identity and the norm-four charge-direction contraction. The span equality extends the identity to the entire grade, including dependent or zero tensors."))), DescribeRole.Theorem),
            Paragraph(Text("These are algebraic statements for arbitrary even integral symmetric lattice data with the stated unit determinant and norm-four charge. Positivity, rootlessness, rank twenty-four, a chosen eigenbasis and an additional positive-rank premise are unnecessary. The construction is classical: Frenkel-Lepowsky-Meurman, Vertex Operator Algebras and the Monster; Dong-Nagatomo, arXiv:math/9808088, section 3.2; Bakalov-Kac, arXiv:math/0402315, section 4. The ordinary norm-four vector follows the formula cited by Shimakura, arXiv:1202.6107, equation (1.3).")))));
}
